func (b *bleveBackend) TotalDocs() int64 {
	b.cacheMu.Lock()
	defer b.cacheMu.Unlock()

	var totalDocs int64
	for _, v := range b.cache {
		c, err := v.index.DocCount()
		if err != nil {
			continue
		}
		totalDocs += int64(c)
	}
	return totalDocs

